import crypto from 'node:crypto'; import fs from 'node:fs'; import path from 'node:path'; import * as XLSXModule from 'xlsx'; import { PDFDocument, StandardFonts } from 'pdf-lib'; const XLSX:any=(XLSXModule as any).default||XLSXModule;
export const BATCH_WORKSPACE_ID='ws-academy-mixed-source-batch'; export const BATCH_ENGAGEMENT_ID='eng-academy-mixed-source-batch'; export const BATCH_RECEIPT_DOCUMENT_ID='doc-batch-receipt';
export const BATCH_VALUES={IMAGE:53.23,SPREADSHEET:53.24,PDF:53.25,CSV:53.26} as const;
export function batchEvidenceDir(){return process.env.MIXED_SOURCE_BATCH_ACCEPTANCE_EVIDENCE_DIR||'/tmp/eve-mixed-source-batch';}
export function batchPath(name:string){return path.join(batchEvidenceDir(),name);} export const sha256=(b:Buffer)=>crypto.createHash('sha256').update(b).digest('hex');
export function buildBatchSpreadsheet():Buffer{const wb:any=XLSX.utils.book_new();wb.Props={Title:'Eve Mixed Source Batch Spreadsheet',Author:'Eve Academy',CreatedDate:new Date('2026-09-16T00:00:00Z'),ModifiedDate:new Date('2026-09-16T00:00:00Z')};const ws=XLSX.utils.aoa_to_sheet([['Description','Amount','Currency'],['Spreadsheet batch evidence',BATCH_VALUES.SPREADSHEET,'USD']]);ws.B2.z='$0.00';XLSX.utils.book_append_sheet(wb,ws,'Expense Register');return Buffer.from(XLSX.write(wb,{type:'buffer',bookType:'xlsx',compression:true,cellStyles:true}));}
export function buildBatchCsv():Buffer{return Buffer.from(`Description,Amount,Currency\nCSV batch evidence,${BATCH_VALUES.CSV.toFixed(2)},USD\n`,'utf8');}
export async function buildBatchPdf():Promise<Buffer>{const doc=await PDFDocument.create();doc.setTitle('Eve Mixed Source Batch PDF');doc.setAuthor('Eve Academy');doc.setCreator('Eve Academy Fixture Generator');doc.setProducer('Eve Academy Fixture Generator');doc.setCreationDate(new Date('2026-09-16T00:00:00Z'));doc.setModificationDate(new Date('2026-09-16T00:00:00Z'));const page=doc.addPage([612,792]);const font=await doc.embedFont(StandardFonts.Helvetica);page.drawText(`PDF Batch Evidence Amount USD ${BATCH_VALUES.PDF.toFixed(2)}`,{x:72,y:700,size:14,font});return Buffer.from(await doc.save({useObjectStreams:false,addDefaultPage:false}));}
export function loadBatchFile(name:string):Buffer{return fs.readFileSync(batchPath(name));}
